import sys, struct, hashlib
sys.path.insert(0,'/tmp/an')
from quicdec import *

def load_keylog(path):
    sec={}
    for l in open(path):
        p=l.split()
        if len(p)==3: sec[(p[0],p[1])]=bytes.fromhex(p[2])
    return sec

def keylog_by_random(path):
    d={}
    for (label,r),v in load_keylog(path).items():
        d.setdefault(r,{})[label]=v
    return d

def read_wire(path):
    pkts=[]
    cur=None
    for l in open(path):
        if l.startswith('    '):
            cur[1].append(l.split()[1])
        elif '->' in l:
            parts=l.split()
            cur=[parts[2], int(parts[3].split(':')[1]), int(parts[1]), []]
            pkts.append(cur)
    out=[]
    for d,port,ts,hl in pkts:
        out.append((d,port,ts,bytes.fromhex(''.join(hl))))
    return out

def try_header(ciph, hp, hdr, payload, pn_off, maxpn=4):
    sample = payload[maxpn:maxpn+16]
    mask = ecb(ciph, hp, sample)
    pb = bytearray(hdr)
    pb[0] ^= mask[0]&0x1f
    pnlen = (pb[0] & 3)+1
    for i in range(pnlen):
        pb[pn_off+pnlen-1-i] ^= mask[1+i]
    return bytes(pb), mask, pnlen
