{"command": "cd /tmp/an && python3 - <<'PY'
import ctypes, os
from quicdec import *
def dec3(ciph,key,iv,aad,ct,tag,ctrl,post,fname):
    ctx=ctypes.c_void_p(lc.EVP_CIPHER_CTX_new())
    assert lc.EVP_CipherInit_ex2(ctx,ciph,key,iv,0,None)==1
    tb=ctypes.create_string_buffer(tag,len(tag))
    r=0
    if not post: r=lc.EVP_CIPHER_CTX_ctrl(ctx,ctrl,len(tag),tb)
    out=ctypes.create_string_buffer(len(ct)+64); n=ctypes.c_int(0)
    if aad: lc.EVP_CipherUpdate(ctx,ctypes.create_string_buffer(64),ctypes.byref(ctypes.c_int(0)),aad,len(aad))
    if ct: lc.EVP_CipherUpdate(ctx,out,ctypes.byref(n),ct,len(ct))
    if post: r=lc.EVP_CIPHER_CTX_ctrl(ctx,ctrl,len(tag),tb)
    out2=ctypes.create_string_buffer(32); n2=ctypes.c_int(0)
    if fname=='ex': rc=lc.EVP_CipherFinal_ex(ctx,out2,ctypes.byref(n2))
    else: rc=lc.EVP_DecryptFinal_ex(ctx,out2,ctypes.byref(n2))
    return out.raw[:n.value]==None, r, rc
k=os.urandom(32); iv=os.urandom(12); aad=os.urandom(20); data=os.urandom(100)
for ciph,name in [(CHACHA,'chacha'),(AES256GCM,'aes256')]:
    ct,tag=enc(ciph,k,iv,aad,data,None,1)
    for ctrl in (0x10,0x11):
        for post in (False,True):
            for fname in ('ex','dec'):
                _,r,rc=dec3(ciph,k,iv,aad,ct,tag,ctrl,post,fname)
                print(name,hex(ctrl),post,fname,"ctrl",r,"final",rc)
PY"}

