{"command": "cd /tmp/an && python3 - <<'PY'
import sys; sys.path.insert(0,'/tmp/an')
from an import *
wire=read_wire('/tmp/an/wire.log')
sec=load_secrets('/tmp/an/ckey.txt'); sec.update(load_secrets('/tmp/an/skey.txt'))
nms=['CLIENT_HANDSHAKE_TRAFFIC_SECRET','SERVER_HANDSHAKE_TRAFFIC_SECRET','CLIENT_TRAFFIC_SECRET_0','SERVER_TRAFFIC_SECRET_0']
def dec_short(data, secret, suite, pn_off, dcidlen):
    c,k,iv,hp,e,klen=keys_for(secret,suite)
    mask=ecb(e,hp,data[pn_off+4:pn_off+4+16])
    b0=data[0]^(mask[0]&0x1f)
    pnlen=(b0&3)+1
    ptr=bytearray(data[pn_off:pn_off+pnlen])
    for i in range(pnlen): ptr[pnlen-1-i]^=mask[1+i]
    ptr=int.from_bytes(bytes(ptr),'big')
    aad=bytes(data[:pn_off])+bytes([b0])+ptr.to_bytes(pnlen,'big')
    nonce=bytes(a^b for a,b in zip(iv,(ptr&0xffffffff).to_bytes(12,'big')))
    p=dec(c,k,nonce,aad,data[pn_off+pnlen:-16],None)
    return p
for i in range(3,6):
    d,p,ts,data=wire[i]
    print("datagram",i,len(data),hex(data[0]))
    for dcidlen in (8,16,20):
        pn_off=1+dcidlen
        for nm in nms:
            for suite in ['AES-128-GCM','AES-256-GCM','ChaCha20-Poly1305']:
                try:
                    q=dec_short(data,sec[nm],suite,pn_off,dcidlen)
                except Exception as e:
                    q=b''
                if len(q)>=16 and (q[0] in (0,1,2,3,6,8,0x18,0x1a,0x1d,0x1f) or q[:2] in (b'\x02\x',b'\x06')):
                    print("  ",dcidlen,nm,suite,q[:24].hex())
PY"}

