from an import read_wire, vi
from full import frames
from np2 import split_pkts
def frames_at(data, o, end):
    """parse frames in data[o:end]; return list or None"""
    try:
        fs=frames(data[o:end])
    except Exception: return None
    if not fs: return None
    if any(f[0]=='UNKNOWN' for f in fs): return None
    return fs
def parse_pkt(data, o, end, pn_off):
    """try pnlen 1..4; return (pnlen, frames)"""
    payload_end = end-16
    for pnlen in (1,2,3,4):
        s=pn_off+pnlen
        if s>payload_end: continue
        fs=frames_at(data, s, payload_end)
        if fs is None: continue
        if len(data[s:payload_end])==0: continue
        return pnlen, fs
    return None
def extract(path, side=None, maxn=1000):
    wire=read_wire(path)
