//! Authenticated encryption: AES-128/256-GCM and ChaCha20-Poly1305.
//! Written from scratch following RFC 5116 / RFC 5288 / RFC 8439.

// ---------------------------------------------------------------- AES -----
fn gmul(mut a: u8, mut b: u8) -> u8 {
    let mut p = 0u8;
    for _ in 0..8 {
        if b & 1 != 0 { p ^= a; }
        let hi = a & 0x80;
        a <<= 1;
        if hi != 0 { a ^= 0x1b; }
        b >>= 1;
    }
    p
}
fn inv(a: u8) -> u8 {
    if a == 0 { return 0; }
    for i in 1..=255u8 { if gmul(a, i) == 1 { return i; } }
    0
}
pub struct Sbox(pub [u8; 256]);
pub static SBOX: Sbox = {
    let mut t = [0u8; 256];
    let mut i = 0usize;
    // sbox computed at first use instead; const fn cannot loop over runtime values, so we
    // build it with a static table of the standard AES S-box.
    while i < 256 { t[i] = 0; i += 1; }
    Sbox(t)
};

// The AES S-box, generated by hand: s(x) = B(x^-1) where B is the affine map.
pub fn sbox() -> [u8; 256] {
    let mut t = [0u8; 256];
    for x in 0..256usize {
        let a = x as u8;
        let b = inv(a);
        let mut v = b;
        let mut r = 0u8;
        for i in 0..8 {
            let bit = (b >> i) & 1;
            let s = (b >> ((i + 4) % 8)) & 1 ^ (b >> ((i + 5) % 8)) & 1 ^ (b >> ((i + 6) % 8)) & 1
                ^ (b >> ((i + 7) % 8)) & 1 ^ (b >> ((i + 8) % 8)) & 1 ^ 0x63 >> i & 1;
            let _ = (bit, s);
        }
        // affine: b ^ rotl(b,1) ^ rotl(b,2) ^ rotl(b,3) ^ rotl(b,4) ^ 0x63
        let rot = |x: u8, n: u32| x.rotate_left(n);
        v = b ^ rot(b, 1) ^ rot(b, 2) ^ rot(b, 3) ^ rot(b, 4) ^ 0x63;
        r = v;
        t[x] = r;
    }
    t
}

pub struct Aes {
    pub nr: usize,
    pub rk: [[u8; 16]; 15],
}

impl Aes {
    pub fn new(key: &[u8]) -> Aes {
        let nk = key.len() / 4;
        let nr = nk + 6;
        let s = sbox();
        let mut w = vec![0u32; 4 * (nr + 1)];
        for i in 0..nk {
            w[i] = u32::from_be_bytes([key[4 * i], key[4 * i + 1], key[4 * i + 2], key[4 * i + 3]]);
        }
        let mut rcon = 1u8;
        let mut i = nk;
        while i < 4 * (nr + 1) {
            let mut t = w[i - 1];
            if i % nk == 0 {
                t = sub_word(t, &s).rotate_left(8) ^ (rcon as u32);
                rcon = gmul(rcon, 2);
            } else if nk > 6 && i % nk == 4 {
                t = sub_word(t, &s);
            }
            w[i] = w[i - nk] ^ t;
            i += 1;
        }
        let mut rk = [[0u8; 16]; 15];
        for r in 0..=nr {
            for c in 0..4 {
                rk[r][4 * c..4 * c + 4].copy_from_slice(&w[r * 4 + c].to_be_bytes());
            }
        }
        Aes { nr, rk }
    }

    pub fn encrypt_block(&self, block: &mut [u8; 16]) {
        let s = sbox();
        let mut st = [0u8; 16];
        st.copy_from_slice(block);
        add_round_key(&mut st, &self.rk[0]);
        for r in 1..self.nr {
            sub_bytes(&mut st, &s);
            shift_rows(&mut st);
            mix_columns(&mut st);
            add_round_key(&mut st, &self.rk[r]);
        }
        sub_bytes(&mut st, &s);
        shift_rows(&mut st);
        add_round_key(&mut st, &self.rk[self.nr]);
        block.copy_from_slice(&st);
    }
}
fn sub_word(x: u32, s: &[u8; 256]) -> u32 {
    let b = x.to_be_bytes();
    u32::from_be_bytes([s[b[0] as usize], s[b[1] as usize], s[b[2] as usize], s[b[3] as usize]])
}
fn add_round_key(st: &mut [u8; 16], k: &[u8; 16]) {
    for i in 0..16 { st[i] ^= k[i]; }
}
fn sub_bytes(st: &mut [u8; 16], s: &[u8; 256]) {
    for i in 0..16 { st[i] = s[st[i] as usize]; }
}
fn shift_rows(st: &mut [u8; 16]) {
    let c = st;
    for r in 1..4 {
        for c0 in 0..4 {
            st[4 * c0 + r] = c[4 * ((c0 + r) % 4) + r];
        }
    }
}
fn mix_columns(st: &mut [u8; 16]) {
    for c0 in 0..4 {
        let a = [st[4 * c0], st[4 * c0 + 1], st[4 * c0 + 2], st[4 * c0 + 3]];
        st[4 * c0] = gmul(a[0], 2) ^ gmul(a[1], 3) ^ a[2] ^ a[3];
        st[4 * c0 + 1] = a[0] ^ gmul(a[1], 2) ^ gmul(a[2], 3) ^ a[3];
        st[4 * c0 + 2] = a[0] ^ a[1] ^ gmul(a[2], 2) ^ gmul(a[3], 3);
        st[4 * c0 + 3] = gmul(a[0], 3) ^ a[1] ^ a[2] ^ gmul(a[3], 2);
    }
}

// --------------------------------------------------------------- GHASH ----
fn gf128_mul(x: &[u8; 16], y: &[u8; 16]) -> [u8; 16] {
    let mut z = [0u8; 16];
    let mut v = *y;
    for i in 0..128 {
        let bit = (x[i / 8] >> (7 - (i % 8))) & 1;
        if bit == 1 {
            for j in 0..16 { z[j] ^= v[j]; }
        }
        let lsb = v[15] & 1;
        // v >>= 1
        for j in (1..16).rev() {
            v[j] = (v[j] >> 1) | (v[j - 1] << 7);
        }
        v[0] >>= 1;
        if lsb == 1 { v[0] ^= 0xe1; }
    }
    z
}

/// AES-GCM as used by TLS/QUIC: 12-byte nonce, 16-byte tag.
pub struct AesGcm {
    aes: Aes,
    h: [u8; 16],
}
impl AesGcm {
    pub fn new(key: &[u8]) -> AesGcm {
        let aes = Aes::new(key);
