    }
    fn j0(&self, nonce: &[u8]) -> [u8; 16] {
        let mut j = [0u8; 16];
        if nonce.len() == 12 {
            j[..12].copy_from_slice(nonce);
            j[15] = 1;
        } else {
            let mut buf = vec![];
            buf.extend_from_slice(nonce);
            while buf.len() % 16 != 0 { buf.push(0); }
            buf.extend_from_slice(&((nonce.len() as u64) * 8).to_be_bytes());
            let mut y = [0u8; 16];
            let mut i = 0;
            while i < buf.len() {
                let mut blk = [0u8; 16];
                blk.copy_from_slice(&buf[i..i + 16]);
                for k in 0..16 { y[k] ^= blk[k]; }
                y = gf128_mul(&y, &self.h);
                i += 16;
            }
            for k in 0..16 { y[k] ^= self.h[k]; }
            let mut z = [0u8; 16];
            z.copy_from_slice(&y);
            self.aes.encrypt_block(&mut z);
            j = z;
        }
