    }
    fn ghash(&self, aad: &[u8], ct: &[u8]) -> [u8; 16] {
        let mut y = [0u8; 16];
        let mut proc = |y: &mut [u8; 16], data: &[u8]| {
            let mut i = 0;
            while i < data.len() {
                let n = std::cmp::min(16, data.len() - i);
                let mut blk = [0u8; 16];
                blk[..n].copy_from_slice(&data[i..i + n]);
                for k in 0..16 { y[k] ^= blk[k]; }
