    for i in 0..8 { st[4 + i] = u32::from_le_bytes(key[4 * i..4 * i + 4].try_into().unwrap()); }
    st[12] = counter;
    for i in 0..3 { st[13 + i] = u32::from_le_bytes(nonce[4 * i..4 * i + 4].try_into().unwrap()); }
    let mut w = st;
    for _ in 0..10 {
