cd /workspace && python3 - <<'PY'
s=open('src/crypto/aead.rs').read()
i=s.index('fn poly_reduce(v: &mut Vec<u64>) {')
j=s.index('pub fn reduce_pub')
new = '''fn add_limbs(a: &[u64], b: &[u64]) -> Vec<u64> {
    let n = a.len().max(b.len()) + 1;
    let mut r = vec![0u64; n];
    let mut carry = 0u128;
    for idx in 0..n {
        let x = if idx < a.len() { a[idx] as u128 } else { 0 };
        let y = if idx < b.len() { b[idx] as u128 } else { 0 };
        let t = x + y + carry;
        r[idx] = t as u64;
        carry = t >> 64;
    }
    while r.len() > 1 && r[r.len() - 1] == 0 { r.pop(); }
    r
}
fn poly_reduce(v: &mut Vec<u64>) {
    loop {
        let mut len = v.len();
        while len > 0 && v[len - 1] == 0 { len -= 1; }
        if len == 0 { *v = vec![0]; return; }
        // lo = value mod 2^130 (limbs), hi = value >> 130
        let lo = vec![v[0], v[1], v[2] & 3];
        let mut hi: Vec<u64> = Vec::new();
        let mut j = 0usize;
        loop {
            let a = if j + 2 < len { v[j + 2] } else { 0 };
            let b = if j + 3 < len { v[j + 3] } else { 0 };
            let t = (a >> 2) | ((b & 3) << 62);
            if t == 0 && j > 0 && j + 2 >= len { break; }
            if t == 0 && j + 2 >= len { break; }
            hi.push(t);
            j += 1;
            if j > len + 2 { break; }
        }
        while hi.len() > 0 && hi[hi.len() - 1] == 0 { hi.pop(); }
        if hi.is_empty() {
            *v = lo;
            return;
        }
        let five = poly_mul(&hi, &[5]);
        let mut res = add_limbs(&lo, &five);
        while res.len() > 0 && res[res.len() - 1] == 0 { res.pop(); }
        if res.len() < 3 { res.resize(3, 0); }
        *v = res;
    }
}
'''
s = s[:i] + new + s[j:]
open('src/crypto/aead.rs','w').write(s)
PY
