mod crypto;
fn hex(b:&[u8])->String{ b.iter().map(|x|format!("{:02x}",x)).collect() }
fn main(){
  let key:[u8;32]=(0u8..32).collect::<Vec<u8>>().try_into().unwrap();
  println!("16xff: {} (want 901295179a1c9f21a426a92bae30b335)", hex(&crypto::aead::poly1305_pub(&key,&vec![0xffu8;16])));
  println!("17xff: {} (want 3373fa42ec95df68d1b8be82a4c37f78)", hex(&crypto::aead::poly1305_pub(&key,&vec![0xffu8;17])));
  println!("msg:   {} (want 6a1c0d19f72175c9009b6e8162c58fc4)", hex(&crypto::aead::poly1305_pub(&key,b"Cryptographic Forum Research Group")));
  let key = (0u8..32).collect::<Vec<u8>>();
  let nonce = [0u8,0,0,0,0,1,2,3,4,5,6,7];
  let aad: [u8;12] = [0x50,0x51,0x52,0x53,0xc0,0xc1,0xc2,0xc3,0xc4,0xc5,0xc6,0xc7];
  let pt = b"Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunburn would be it.";
  let keya: [u8;32] = key.clone().try_into().unwrap();
  let ct = crypto::aead::ChaCha20Poly1305::encrypt(&keya, &nonce, &aad, pt);
  println!("ccp tag: {} (openssl 33c699685f16255acad56dde2edbc71c)", hex(&ct[ct.len()-16..]));
  println!("roundtrip: {}", crypto::aead::ChaCha20Poly1305::decrypt(&keya,&nonce,&aad,&ct).unwrap()==pt);
}
EOF
