//! X25519 (RFC 7748) curve arithmetic over GF(2^255-19), 5 limbs of 51 bits.
pub type Fe = [u64; 5];
const MASK: u64 = (1u64 << 51) - 1;

fn load(b: &[u8]) -> Fe {
    // 32-byte little-endian to 5x51-bit limbs
    let mut l = [0u64; 5];
    let mut acc: u128 = 0;
    let mut bits = 0usize;
    let mut li = 0usize;
    for &byte in b {
        acc |= (byte as u128) << bits;
        bits += 8;
        while bits >= 51 && li < 5 {
            l[li] = (acc & MASK as u128) as u64;
            acc >>= 51;
            bits -= 51;
            li += 1;
        }
    }
    while li < 5 { l[li] = (acc & MASK as u128) as u64; acc >>= 51; bits -= 51; li += 1; }
    l
