    let top = t[4] >> 51;
    t[4] &= MASK;
    let mut v = [0u64; 5];
    v[0] = t[0] + top * 19;
    carry(&mut v);
    // if still >= 2^255-19 subtract
    let mut out = [0u8; 32];
