fn carry(f: &mut Fe) {
    for i in 0..4 {
        let c = f[i] >> 51;
        f[i] &= MASK;
        f[i + 1] += c;
    }
    let c = f[4] >> 51;
    f[4] &= MASK;
    f[0] += c * 19;
    let c = f[0] >> 51;
    f[0] &= MASK;
    f[1] += c;
