//! Performance test client/server application layer.
use crate::cli::Common;
use crate::log::{error, warn};

/// Parse a size string with SI suffixes (1M = 1MiB).
pub fn parse_size(s: &str) -> Option<u64> {
    let s = s.trim();
    if s.is_empty() { return None; }
    let (num, mult) = match s.chars().last().unwrap() {
        'k' | 'K' => (&s[..s.len() - 1], 1024u64),
        'm' | 'M' => (&s[..s.len() - 1], 1024u64 * 1024),
        'g' | 'G' => (&s[..s.len() - 1], 1024u64 * 1024 * 1024),
        't' | 'T' => (&s[..s.len() - 1], 1024u64 * 1024 * 1024 * 1024),
        _ => (s, 1),
    };
    num.parse::<u64>().ok().map(|v| v.saturating_mul(mult))
}

pub fn run(c: Common, is_server: bool) -> i32 {
    let target = if is_server { "quinn_perf" } else { "quinn_perf" };
    let _ = target;
