            Err(e) => {
                error("quinn_perf", &format!("binding endpoint: {}", e));
                return 0;
            }
            Ok(sock) => crate::server::serve(sock, c),
        }
    } else {
        let send = crate::net::socket_send_buffer();
        let recv = crate::net::socket_recv_buffer();
        if send < 2097152 {
            warn("perf", &format!("Unable to set desired send buffer size. Desired: 2097152, Actual: {}", send));
        }
        if recv < 2097152 {
            warn("perf", &format!("Unable to set desired recv buffer size. Desired: 2097152, Actual: {}", recv));
        }
        crate::client::run_client(c)
    }
}
