/// Options accepted by both subcommands.
#[derive(Default, Clone, Debug)]
pub struct Common {
    pub listen: String,
    pub host: String,
    pub send_buffer_size: String,
    pub recv_buffer_size: String,
    pub conn_stats: bool,
    pub keylog: bool,
    pub initial_mtu: String,
    pub no_protection: bool,
    pub initial_rtt: Option<String>,
    pub ack_frequency: bool,
    pub congestion: Option<String>,
    pub stream_receive_window: Option<String>,
    pub receive_window: Option<String>,
    pub send_window: Option<String>,
    pub max_udp_payload_size: String,
    pub qlog: Option<String>,
    pub cert: Option<String>,
    pub key: Option<String>,
    pub ip: Option<String>,
    pub local_addr: Option<String>,
    pub uni_requests: String,
    pub bi_requests: String,
    pub download_size: String,
    pub upload_size: String,
    pub duration: String,
    pub interval: String,
    pub json: Option<String>,
}

fn is_flag(name: &str) -> bool {
    matches!(name, "--conn-stats" | "--keylog" | "--no-protection" | "--ack-frequency")
}

fn takes_value(name: &str) -> bool {
    matches!(name,
        "--listen" | "--host" | "--send-buffer-size" | "--recv-buffer-size" | "--initial-mtu"
        | "--initial-rtt" | "--congestion" | "--stream-receive-window" | "--receive-window"
        | "--send-window" | "--max-udp-payload-size" | "--qlog" | "--cert" | "--key" | "--ip"
        | "--local-addr" | "--uni-requests" | "--bi-requests" | "--download-size"
        | "--upload-size" | "--duration" | "--interval" | "--json")
}

fn set(c: &mut Common, name: &str, val: Option<String>) -> Result<(), String> {
    match name {
        "--listen" => c.listen = val.unwrap(),
        "--send-buffer-size" => c.send_buffer_size = val.unwrap(),
        "--recv-buffer-size" => c.recv_buffer_size = val.unwrap(),
        "--initial-mtu" => c.initial_mtu = val.unwrap(),
        "--initial-rtt" => c.initial_rtt = Some(val.unwrap()),
        "--congestion" => {
            let v = val.unwrap();
            if !["cubic", "bbr", "new-reno"].contains(&v.as_str()) {
                return Err(format!("invalid value '{}' for '--congestion <CONG_ALG>'\n  [possible values: cubic, bbr, new-reno]", v));
            }
            c.congestion = Some(v);
        }
        "--stream-receive-window" => c.stream_receive_window = Some(val.unwrap()),
        "--receive-window" => c.receive_window = Some(val.unwrap()),
        "--send-window" => c.send_window = Some(val.unwrap()),
        "--max-udp-payload-size" => c.max_udp_payload_size = val.unwrap(),
        "--qlog" => c.qlog = Some(val.unwrap()),
        "--cert" => c.cert = Some(val.unwrap()),
        "--key" => c.key = Some(val.unwrap()),
        "--ip" => c.ip = Some(val.unwrap()),
        "--local-addr" => c.local_addr = Some(val.unwrap()),
        "--uni-requests" => c.uni_requests = val.unwrap(),
        "--bi-requests" => c.bi_requests = val.unwrap(),
        "--download-size" => c.download_size = val.unwrap(),
        "--upload-size" => c.upload_size = val.unwrap(),
        "--duration" => c.duration = val.unwrap(),
        "--interval" => c.interval = val.unwrap(),
        "--json" => c.json = Some(val.unwrap()),
        "--conn-stats" => c.conn_stats = true,
        "--keylog" => c.keylog = true,
        "--no-protection" => c.no_protection = true,
        "--ack-frequency" => c.ack_frequency = true,
        _ => return Err(format!("unrecognized option {}", name)),
    }
    Ok(())
}

const ROOT_USAGE: &str = "executable <COMMAND>";
const SERVER_USAGE: &str = "executable server [OPTIONS]";
const CLIENT_USAGE: &str = "executable client [OPTIONS] [HOST]";

fn parse_args(args: &[String], is_server: bool) -> Result<Common, String> {
    let mut c = Common::default();
    if is_server {
        c.listen = "[::]:4433".to_string();
    } else {
        c.host = "localhost:4433".to_string();
        c.uni_requests = "0".to_string();
        c.bi_requests = "1".to_string();
        c.download_size = "1M".to_string();
        c.upload_size = "1M".to_string();
        c.duration = "60".to_string();
        c.interval = "1".to_string();
    }
    c.send_buffer_size = "2M".to_string();
    c.recv_buffer_size = "2M".to_string();
    c.initial_mtu = "1200".to_string();
    c.max_udp_payload_size = "1472".to_string();
    let usage = if is_server { SERVER_USAGE } else { CLIENT_USAGE };
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "--help" {
            print_help(if is_server { SERVER_HELP } else { CLIENT_HELP });
            std::process::exit(0);
        }
        if a == "-h" {
            print_help(if is_server { SERVER_HELP_SHORT } else { CLIENT_HELP_SHORT });
            std::process::exit(0);
        }
        if let Some(rest) = a.strip_prefix("--") {
            let (name, inline) = match rest.find('=') {
                Some(p) => (&a[..2 + p], Some(a[2 + p + 1..].to_string())),
                None => (a.as_str(), None),
            };
            if is_flag(name) {
                if inline.is_some() {
                    return Err(format!("unexpected value '{}' for '--{}' found; no more were expected", inline.unwrap(), &name[2..]));
                }
                if let Err(e) = set(&mut c, name, None) { return Err(e); }
                i += 1;
                continue;
            }
            if takes_value(name) {
                let v = match inline {
                    Some(v) => { i += 1; v }
                    None => {
                        i += 1;
                        if i >= args.len() {
                            return Err(format!("a value is required for '{}' but none was supplied", name));
                        }
                        args[i].clone()
                    }
                };
                if let Err(e) = set(&mut c, name, Some(v)) { return Err(e); }
                i += 1;
                continue;
            }
            return Err(format!("unexpected argument '{}' found", a));
        }
        if a == "-k" || a == "-c" {
            i += 1;
            if i >= args.len() { return Err(format!("a value is required for '{}' but none was supplied", a)); }
            let name = if a == "-k" { "--key" } else { "--cert" };
            if let Err(e) = set(&mut c, name, Some(args[i].clone())) { return Err(e); }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            return Err(format!("unexpected argument '{}' found", a));
        }
        if is_server {
            return Err(format!("unexpected argument '{}' found", a));
        }
        c.host = a.clone();
        i += 1;
    }
    Ok(c)
}

pub fn run() -> i32 {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.is_empty() {
        print!("{}", ROOT_HELP);
        return 0;
    }
    match args[0].as_str() {
        "-h" | "--help" => { print_help(ROOT_HELP); 0 }
        "help" => {
            if args.len() == 1 { print_help(ROOT_HELP); return 0; }
            match args[1].as_str() {
                "server" => { print_help(SERVER_HELP); 0 }
                "client" => { print_help(CLIENT_HELP); 0 }
                "help" => { print_help(HELP_HELP); 0 }
                other => err(&format!("unrecognized subcommand '{}'", other), ROOT_USAGE),
            }
        }
        "server" => crate_run(&args[1..], true),
        "client" => crate_run(&args[1..], false),
        other => err(&format!("unrecognized subcommand '{}'", other), ROOT_USAGE),
    }
}

fn crate_run(args: &[String], is_server: bool) -> i32 {
    let c = match parse_args(args, is_server) {
        Ok(c) => c,
        Err(e) => return err(&e, if is_server { SERVER_USAGE } else { CLIENT_USAGE }),
    };
    crate::perf::run(c, is_server)
}
