//! Minimal reimplementation of the `tracing_subscriber` fmt output format used by the original.
use std::io::Write;
use std::time::{SystemTime, UNIX_EPOCH};

pub fn now_rfc3339() -> String {
    let d = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();
    let secs = d.as_secs();
    let micros = d.subsec_micros();
    let days = secs / 86400;
    let rem = secs % 86400;
    let (h, mi, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // civil_from_days
    let z = days as i64 + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as i64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, m, d, h, mi, s, micros)
}

fn emit(level: &str, color: &str, target: &str, msg: &str) {
    let out = std::io::stderr();
    let mut w = out.lock();
    let _ = writeln!(w,
        "\x1b[2m{}\x1b[0m \x1b[{}m{:>5}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}",
        now_rfc3339(), color, level, target, msg);
}

pub fn warn(target: &str, msg: &str) { emit("WARN", "33", target, msg); }
pub fn error(target: &str, msg: &str) { emit("ERROR", "31", target, msg); }
pub fn info(target: &str, msg: &str) { emit("INFO", "32", target, msg); }
RUSTEOF
